    solve()

from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(x: int) -> int:
            if x <= 0:
                return 0

            digits = tuple(map(int, str(x)))
            n = len(digits)
            total = 0

            for target_sum in range(1, 9 * n + 1):
                @lru_cache(None)
                def dp(
                    pos: int,
                    digit_sum: int,
                    product_mod: int,
                    started: bool,
                    tight: bool,
                ) -> int:
                    remaining = n - pos

                    if digit_sum > target_sum:
                        return 0
                    if digit_sum + 9 * remaining < target_sum:
                        return 0

                    if pos == n:
                        return int(
                            started
                            and digit_sum == target_sum
                            and product_mod == 0
                        )

                    limit = digits[pos] if tight else 9
                    result = 0

                    for digit in range(limit + 1):
                        next_tight = tight and digit == digits[pos]

                        if not started and digit == 0:
                            result += dp(
                                pos + 1,
                                digit_sum,
                                product_mod,
                                False,
                                next_tight,
                            )
                        else:
                            if not started:
                                next_product_mod = digit % target_sum
                            else:
                                next_product_mod = (
                                    product_mod * digit
                                ) % target_sum

                            result += dp(
                                pos + 1,
                                digit_sum + digit,
                                next_product_mod,
                                True,
                                next_tight,
                            )

                    return result

                total += dp(
                    0,
                    0,
                    1 % target_sum,
                    False,
                    True,
                )

            return total

        return count_up_to(r) - count_up_to(l - 1)

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        if n - 1 < k:
            return [0] * n

        children = [{}]
        counts = [0]
        depths = [0]
        paths = []
        max_depth = 0

        for word in words:
            node = 0
            path = []

            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    counts.append(0)
                    depths.append(depths[node] + 1)

                node = nxt
                counts[node] += 1
                path.append(node)

            paths.append(path)
            max_depth = max(max_depth, len(word))

        valid_at_depth = [0] * (max_depth + 1)

        for node in range(1, len(children)):
            if counts[node] >= k:
                valid_at_depth[depths[node]] += 1

        size = 1
        while size <= max_depth:
            size <<= 1

        segment_tree = [0] * (2 * size)

        for depth in range(1, max_depth + 1):
            if valid_at_depth[depth] > 0:
                segment_tree[size + depth] = depth

        for pos in range(size - 1, 0, -1):
            segment_tree[pos] = max(
                segment_tree[pos << 1],
                segment_tree[pos << 1 | 1],
            )

        def update_depth(depth: int, present: bool) -> None:
            pos = size + depth
            segment_tree[pos] = depth if present else 0
            pos >>= 1

            while pos:
                segment_tree[pos] = max(
                    segment_tree[pos << 1],
                    segment_tree[pos << 1 | 1],
                )
                pos >>= 1

        answer = [0] * n

        for i in range(n):
            changed_depths = []

            for node in paths[i]:
                if counts[node] == k:
                    depth = depths[node]
                    valid_at_depth[depth] -= 1

                    if valid_at_depth[depth] == 0:
                        update_depth(depth, False)

                    changed_depths.append(depth)

            answer[i] = segment_tree[1]

            for depth in changed_depths:
                if valid_at_depth[depth] == 0:
                    update_depth(depth, True)
                valid_at_depth[depth] += 1

        return answer

